describe('Invalid Coupon Code Error Message', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="coupon-input"]').should('be.visible');
  });

  it('should display error message when invalid coupon code is entered', () => {
    cy.get('[data-testid="coupon-input"]').type('INVALID123');
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Invalid coupon code');

    cy.get('[data-testid="coupon-discount"]').should('not.exist');
  });

  it('should display error message for expired coupon code', () => {
    cy.get('[data-testid="coupon-input"]').type('EXPIRED2020');
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'This coupon has expired');

    cy.get('[data-testid="order-total"]').should('not.contain', '-');
  });

  it('should clear error message when user corrects the coupon code', () => {
    cy.get('[data-testid="coupon-input"]').type('INVALID123');
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.get('[data-testid="coupon-input"]').clear().type('VALID50');
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="coupon-discount"]').should('contain', '-');
  });

  it('should display error for empty coupon code submission', () => {
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Please enter a coupon code');
  });

  it('should display error for coupon code with special characters', () => {
    cy.get('[data-testid="coupon-input"]').type('INVALID@#$%');
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Invalid coupon code');
  });

  it('should display error message with proper styling and accessibility', () => {
    cy.get('[data-testid="coupon-input"]').type('BADCODE');
    cy.get('[data-testid="apply-coupon-btn"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('have.attr', 'role', 'alert')
      .and('have.css', 'color')
      .and('match', /rgb\(|#/);
  });
});
